using System.Text.Json;
using MphRead;
using MphRead.Mods.CustomWeapons;
using MphRead.Mods.Network;
using OpenTK.Mathematics;

// Derived cosmetic values over supplied accepted facts. No actors or HP writes.
internal static class CustomReplayVisualChecks
{
    internal static int Run(string? output=null)
    {
        int checks=0;string root=Path.GetFullPath(output??Path.Combine(Path.GetTempPath(),"cw12f-visuals-"+Guid.NewGuid().ToString("N")));
        void Check(bool ok,string label){if(!ok)throw new InvalidOperationException(label);checks++;}
        void Near(float actual,float expected,string label)=>Check(MathF.Abs(actual-expected)<.00001f,label);
        void Reject(Action action,string label){try{action();}catch(ArgumentException){Check(true,label);return;}throw new InvalidOperationException("Expected rejection: "+label);}
        try
        {
            Directory.CreateDirectory(root);var foreground=GameState.Current;var random=Rng.Current;string native=JsonSerializer.Serialize(new{Weapons.WeaponsMP,Weapons.Weapons1P});using var f=new CustomReplayStateChecks.Fixture();
            var baseline=f.State(baselineFlight:true);Check(baseline.RiflePose(1,baseline.RecordingFrame).Kick==0&&baseline.RiflePose(1,baseline.RecordingFrame).Flash==0&&!baseline.TryLatestLaunch(f.Launch().Identity.Owner,out _,out _),"baseline retained flight never fabricates accepted-launch flash or kick");
            var state=f.State();var launch=f.Launch();state.Accept(ReplayCustomWeaponFact.Launch(f.Context,state.Sequence+1,launch),20);Check(state.TryLatestLaunch(launch.Identity.Owner,out var latest,out uint at)&&latest==launch&&at==20,"latest accepted launch retains original recording frame");var immediate=state.RiflePose(1,20);Near(immediate.Kick,1,"accepted shot immediate kick");Near(immediate.Flash,1,"accepted shot immediate flash");Near(state.RiflePose(1,20,.5f).Kick,1-.5f/6,"subframe kick interpolation");Near(state.RiflePose(1,22,.5f).Flash,1-2.5f/3,"subframe flash interpolation");Near(state.RiflePose(1,32,.5f).Bolt,4.5f/8,"independent bolt-opening interpolation");Near(state.RiflePose(1,38).Bolt,1,"bolt hold interval");Near(state.RiflePose(1,49).Bolt,.5f,"bolt closing interval");Near(state.RiflePose(1,55).Bolt,0,"bolt settles after accepted shot");
            Check(state.RiflePose(1,20,float.NaN)==state.RiflePose(1,20)&&state.RiflePose(1,20,float.PositiveInfinity)==state.RiflePose(1,20)&&state.RiflePose(1,20,-1)==state.RiflePose(1,20)&&state.RiflePose(1,20,2)==state.RiflePose(1,20,1),"NaN/infinite alpha sanitizes and finite alpha clamps");Check(state.RiflePose(1,19)==default,"presentation query cannot rewind before accepted owner frame");
            var poseBytes=state.CaptureCheckpointBytes();using var fresh=new CustomReplayStateChecks.Fixture();var cold=ReplayCustomWeaponState.RestoreCheckpointBytes(poseBytes,fresh.Context);foreach(uint frame in new uint[]{20,22,28,32,38,49,55})foreach(float alpha in new[]{0f,.25f,.75f,1f})Check(cold.RiflePose(1,frame,alpha)==state.RiflePose(1,frame,alpha),"cold derived pose parity "+frame+"/"+alpha);Check(state.CaptureCheckpointBytes().SequenceEqual(poseBytes),"presentation sampling never mutates retained checkpoint");
            var tie=f.State();tie.Accept(ReplayCustomWeaponFact.Launch(f.Context,tie.Sequence+1,f.Launch(2)),20);tie.Accept(ReplayCustomWeaponFact.Launch(f.Context,tie.Sequence+1,f.Launch(1)),20);Check(tie.TryLatestLaunch(launch.Identity.Owner,out var tied,out _)&&tied.Identity.Sequence==2,"same-frame latest launch uses canonical action sequence rather than arrival");
            var rows=(CustomReplicaSlot[])f.Slots.Clone();rows[1]=rows[1] with{State=rows[1].State with{Tick=1002,Phase=CustomWeaponPhase.Reloading,Magazine=3,ReloadCompleteTick=1002+(uint)f.Context.Definition.Mechanics.ReloadTicks}};state.Accept(ReplayCustomWeaponFact.State(f.Context,state.Sequence+1,1002,rows),21);Near(state.RiflePose(1,21).Magazine,0,"reload begins at retained canonical table tick");state.Accept(ReplayCustomWeaponFact.Clock(f.Context,state.Sequence+1,1002+(uint)f.Context.Definition.Mechanics.ReloadTicks/2),22);Near(state.RiflePose(1,22).Magazine,0,"quiet authority Clock never fabricates source-tick reload progress");state.Accept(ReplayCustomWeaponFact.State(f.Context,state.Sequence+1,state.World,rows),23);Near(state.RiflePose(1,23).Magazine,0,"identical repeated reload source at later world preserves pose");rows[1]=rows[1] with{State=rows[1].State with{Tick=1002+(uint)f.Context.Definition.Mechanics.ReloadTicks/2}};state.Accept(ReplayCustomWeaponFact.State(f.Context,state.Sequence+1,state.World,rows),24);Near(state.RiflePose(1,24).Magazine,1,"accepted source Tick advance derives actual midreload magazine motion");Check(state.RiflePose(1,24).Magazine==state.RiflePose(1,24,1).Magazine,"render alpha cannot advance source-clock reload progress");var reloadCold=ReplayCustomWeaponState.RestoreCheckpointBytes(state.CaptureCheckpointBytes(),fresh.Context);Check(reloadCold.RiflePose(1,24,.5f)==state.RiflePose(1,24,.5f),"cold reload pose preserves exact accepted source progress");
            foreach(string reason in new[]{"unselected","spectating","hidden","oldlife"})
            {
                var fenced=f.State();fenced.Accept(ReplayCustomWeaponFact.Launch(f.Context,fenced.Sequence+1,launch),20);var changed=(CustomReplicaSlot[])f.Slots.Clone();
                if(reason=="unselected")changed[1]=changed[1] with{Selected=default};if(reason=="spectating")changed[1]=new(1,true,5,0,true,false,default,0,0,default);if(reason=="hidden")changed[1]=new(1,false,0,0,false,false,default,0,0,default);if(reason=="oldlife")changed[1]=changed[1] with{Life=11,State=changed[1].State with{Owner=new(7,f.World.Start.AuthorityEpoch,1,5,11)}};
                fenced.Accept(ReplayCustomWeaponFact.State(f.Context,fenced.Sequence+1,1002,changed),21);var pose=fenced.RiflePose(1,21);Check(pose.Kick==0&&pose.Flash==0,reason+" owner cannot replay stale shot cosmetics");
            }
            var contacts=f.State();contacts.Accept(ReplayCustomWeaponFact.Contact(f.Context,contacts.Sequence+1,f.World,f.Contact(2)),20);contacts.Accept(ReplayCustomWeaponFact.Contact(f.Context,contacts.Sequence+1,f.World,f.Contact(1)),20);contacts.Accept(ReplayCustomWeaponFact.Contact(f.Context,contacts.Sequence+1,f.World,f.Contact(3)),21);var values=new ReplayCustomWeaponContact[1024];Check(contacts.CopyContacts(values,20,20)==2&&values[0].Outcome.Contact.Key.Action.Sequence==1&&values[1].Outcome.Contact.Key.Action.Sequence==2&&values[0].Direction==Vector3.Zero,"contact window inclusive/canonical sequence order with unknown launch direction explicitzero");Check(contacts.CopyContacts(values,21,21)==1&&values[0].Outcome==f.Contact(3)&&values[0].RecordingFrame==21,"single contact window preserves exact immutable accepted outcome");Check(contacts.CopyContacts(values,22,30)==0&&contacts.CopyContacts(values,30,20)==0,"empty and reversed windows do not leak contact history");Reject(()=>contacts.CopyContacts(new ReplayCustomWeaponContact[1023],0,100),"contact copy requires complete1024 budget");
            var launched=f.State();launched.Accept(ReplayCustomWeaponFact.Launch(f.Context,launched.Sequence+1,launch),20);launched.Accept(ReplayCustomWeaponFact.Contact(f.Context,launched.Sequence+1,f.World,f.Contact()),21);Check(launched.CopyContacts(values,0,100)==1&&values[0].Direction==launch.Direction,"accepted launch supplies contact direction without inference from victim");var contactCold=ReplayCustomWeaponState.RestoreCheckpointBytes(launched.CaptureCheckpointBytes(),fresh.Context);var coldValues=new ReplayCustomWeaponContact[1024];Check(contactCold.CopyContacts(coldValues,0,100)==1&&coldValues[0]==values[0],"cold contact presentation parity");
            var baselineContact=f.State(baselineFlight:true);baselineContact.Accept(ReplayCustomWeaponFact.Contact(f.Context,baselineContact.Sequence+1,f.World,f.Contact()),20);Check(baselineContact.CopyContacts(values,20,20)==1&&values[0].Direction==f.Flight().Direction,"baseline source anchor supplies contact direction without shot flash");
            var incomplete=f.State(pickups:false);Check(incomplete.RiflePose(1,20)==default&&incomplete.CopyContacts(Array.Empty<ReplayCustomWeaponContact>(),0,100)==0,"incomplete state produces no cosmetics or contact read");Check(ReferenceEquals(foreground,GameState.Current)&&ReferenceEquals(random,Rng.Current)&&JsonSerializer.Serialize(new{Weapons.WeaponsMP,Weapons.Weapons1P})==native,"derived cosmetics leave live game/RNG/native weapon owners untouched");
            File.WriteAllText(Path.Combine(root,"results.json"),JsonSerializer.Serialize(new{checks,scope="Pure derived cosmetic values from supplied accepted facts and cold restore. No native HP mutation, GPU/sound/presenter, authority payment or gameplay replay claim."}));Console.WriteLine($"PASS {checks} custom replay visual derivation checks");return 0;
        }
        catch(Exception error){Console.Error.WriteLine("CUSTOM REPLAY VISUALS FAIL "+error);return 1;}
    }
}
